var isSolo = lootMode === 'solo';
var isList = lootView === 'list';
var isTree = lootView === 'tree';
var isTeam = lootMode === 'team';
var isSoloList = isSolo && isList;
var isSoloTree = isSolo && isTree;
var isTeamView = isTeam;
var total = loot.reduce(function(a,x){ return a+x.value; }, 0);
var totalStr = total.toFixed(2);
var soloList = loot.map(function(x){ return {
  name: x.name, quantity: x.quantity,
  value: x.value.toFixed(2),
  percentage: total ? (x.value / total * 100).toFixed(1) : '0.0'
}; }).sort(function(a,b){ return b.percentage - a.percentage; });
var pad = function(n){ return n < 10 ? '0' + n : '' + n; };
var soloTree = (kills || []).map(function(k){
  var d = new Date(k.time);
  var timeStr = pad(d.getHours())+':'+pad(d.getMinutes())+':'+pad(d.getSeconds());
  return {
    timeStr: timeStr,
    total: k.total.toFixed(2),
    items: k.items.map(function(i){ return { name: i.name, quantity: i.quantity, value: i.value.toFixed(2) }; })
  };
});
var teamPlayers = team ? team.players : [];
var teamLoot = team ? team.loot : [];
var teamSum = teamLoot.length ? teamLoot.map(function(x){ return x.quantity; }).reduce(function(acc,list){ return acc.map(function(q,i){ return q+list[i]; }); }) : [];
var teamTotal = teamSum.length ? teamSum.reduce(function(a,x){ return a+x; }, 0) : 0;
var teamSplit = teamSum.map(function(x){ return teamTotal ? (x / teamTotal * 100).toFixed(1) : '0.0'; });
var teamTable = teamLoot.map(function(x){ return { name: x.name, quantity: x.quantity }; });

cssTemplate:
.loot-toggles {
  display: flex;
  gap: 4px;
  padding: 4px 6px;
}
.loot-toggle {
  padding: 2px 8px;
  border-radius: 3px;
  cursor: pointer;
  font-size: 12px;
  background: color-mix(in srgb, currentColor 8%, transparent);
  opacity: 0.5;
}
.loot-toggle:hover {
  opacity: 0.7;
}
.loot-toggle.active {
  background: rgba(100,160,255,.25);
  opacity: 1;
}
table {
  border-collapse: collapse;
  margin: 0px 6px;
  width: calc(100% - 12px);
}
td, th {
  padding: 2px 5px;
  text-align: end;
}
td:first-child, th:first-child {
  text-align: start;
}
td:nth-child(even), th:nth-child(even) {
  background-color: color-mix(in srgb, currentColor 15%, transparent);
}
.total-row td {
  border-top: 1px solid color-mix(in srgb, currentColor 20%, transparent);
}
.tree {
  padding: 0 6px;
}
.kill-group {
  margin-bottom: 4px;
}
.kill-header {
  font-weight: bold;
  padding: 2px 0;
  border-bottom: 1px solid color-mix(in srgb, currentColor 15%, transparent);
}
.kill-item {
  padding: 1px 0 1px 12px;
  font-size: 12px;
  opacity: 0.75;
}
.tree .total-row {
  padding: 4px 0;
  border-top: 1px solid color-mix(in srgb, currentColor 20%, transparent);
}
